int main(void) {
    /* 1. Enable PWR clock and switch to Range 1 Boost Mode for 170 MHz */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    (void)RCC->APB1ENR1;
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 2. Configure Flash Latency: 4 wait states for 170 MHz in Range 1 Boost */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS);

    /* 3. Enable HSE (12 MHz external crystal) and wait for ready */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY));

    /* 4. Configure Main PLL:
          Source = HSE (12 MHz)
          PLLM   = /3   -> 4 MHz PLL input (M - 1 = 2)
          PLLN   = *85  -> 340 MHz VCO
          PLLR   = /2   -> 170 MHz system clock (0 = div 2)
          Enable PLL_R output (PLLREN) */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   ((3 - 1) << RCC_PLLCFGR_PLLM_Pos) |
                   (85 << RCC_PLLCFGR_PLLN_Pos) |
                   (0 << RCC_PLLCFGR_PLLR_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* 5. Enable PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* 6. Switch SYSCLK to PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

    /* 7. Enable peripheral clocks for GPIOA, GPIOB, USART2, and I2C1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOBEN;
    (void)RCC->AHB2ENR;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN | RCC_APB1ENR1_I2C1EN;
    (void)RCC->APB1ENR1;

    /* 8. Configure GPIO Pins:
          PA2: USART2_TX -> AF7, Push-Pull, High Speed
          PA3: USART2_RX -> AF7, Input / Floating
          PB8: I2C1_SCL  -> AF4, Open-Drain, Pull-up enabled
          PB9: I2C1_SDA  -> AF4, Open-Drain, Pull-up enabled */

    /* Configure PA2 and PA3 */
    GPIOA->MODER = (GPIOA->MODER & ~(GPIO_MODER_MODE2 | GPIO_MODER_MODE3)) |
                   (GPIO_MODER_MODE2_1 | GPIO_MODER_MODE3_1);
    GPIOA->AFR[0] = (GPIOA->AFR[0] & ~((0xF << GPIO_AFRL_AFSEL2_Pos) | (0xF << GPIO_AFRL_AFSEL3_Pos))) |
                    (7 << GPIO_AFRL_AFSEL2_Pos) |
                    (7 << GPIO_AFRL_AFSEL3_Pos);
    GPIOA->OSPEEDR |= GPIO_OSPEEDR_OSPEED2;

    /* Configure PB8 and PB9 */
    GPIOB->MODER = (GPIOB->MODER & ~(GPIO_MODER_MODE8 | GPIO_MODER_MODE9)) |
                   (GPIO_MODER_MODE8_1 | GPIO_MODER_MODE9_1);
    GPIOB->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);
    GPIOB->AFR[1] = (GPIOB->AFR[1] & ~((0xF << GPIO_AFRH_AFSEL8_Pos) | (0xF << GPIO_AFRH_AFSEL9_Pos))) |
                    (4 << GPIO_AFRH_AFSEL8_Pos) |
                    (4 << GPIO_AFRH_AFSEL9_Pos);
    GPIOB->OSPEEDR |= (GPIO_OSPEEDR_OSPEED8 | GPIO_OSPEEDR_OSPEED9);
    GPIOB->PUPDR = (GPIOB->PUPDR & ~(GPIO_PUPDR_PUPD8 | GPIO_PUPDR_PUPD9)) |
                   (GPIO_PUPDR_PUPD8_0 | GPIO_PUPDR_PUPD9_0);

    /* 9. Configure USART2:
          Clock = PCLK1 = 170 MHz, OVER8 = 0 (16x oversampling)
          Baud = 921600 -> BRR = round(170,000,000 / 921600) = 184
          Actual baud = 923913 (+0.25% error)
          8 data bits, 1 stop bit, Transmitter & Receiver enabled */
    USART2->CR1 = 0;
    USART2->CR2 = 0;
    USART2->CR3 = 0;
    USART2->BRR = 184;
    USART2->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* 10. Configure I2C1:
