    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY));
    RCC->CCIPR = (RCC->CCIPR & ~RCC_CCIPR_I2C1SEL) | RCC_CCIPR_I2C1SEL_1;

    /* Disable peripheral before programming TIMINGR */
    I2C1->CR1 &= ~I2C_CR1_PE;
    /* Standard-mode 100 kHz (RM0440 Table 360, fI2CCLK = 16 MHz):
       PRESC = 3, SCLL = 0x13, SCLH = 0x0F, SDADEL = 0x2, SCLDEL = 0x4 */
    I2C1->TIMINGR = 0x30420F13;
    I2C1->CR1 |= I2C_CR1_PE;

    /* Bring-up complete; loop forever */
    while (1) {
    }
}
