     * PLLN   = 85 (value = 85)            -> 4 MHz * 85 = 340 MHz VCO
     * PLLR   = 2 (value = 0: (0b00 + 1) * 2 / wait, bit 26:25: 00 = /2) -> 340 / 2 = 170 MHz
     * Enable PLLR output
     */
    RCC->PLLCFGR = (3UL << RCC_PLLCFGR_PLLSRC_Pos)
                 | (3UL << RCC_PLLCFGR_PLLM_Pos)
                 | (85UL << RCC_PLLCFGR_PLLN_Pos)
                 | (0UL << RCC_PLLCFGR_PLLR_Pos)
                 | RCC_PLLCFGR_PLLREN;

    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Wait for PLL lock */
    }

